const stmt = db.prepare(`INSERT OR IGNORE INTO jobs
  (id,title,location,salary,job_type,employment_type,description,tags,image_url,catchcopy,faq,is_published,target_media,published_at,expires_at,company,created_at,updated_at)
  VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)`);

let added = 0, skipped = 0;
for (const j of JOBS) {
  const before = db.prepare('SELECT id FROM jobs WHERE id = ?').get(j.id);
  if (before) { skipped++; continue; }
  stmt.run(j.id,j.title,j.location,j.salary,j.job_type,j.employment_type,j.description,j.tags,j.image_url,j.catchcopy,j.faq,j.is_published,j.target_media,j.published_at,j.expires_at,j.company,j.created_at,j.updated_at);
  added++;
}
console.log(`✅ 求人復元完了: 追加 ${added}件 / スキップ ${skipped}件`);
